{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 금연구역 지정 공원 내 흡연부스 설치 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시가 금연구역으로 지정한 공원 안에도 흡연부스(흡연구역)를 설치·운영할 수 있습니다. 이는 해당 장소의 소유자·점유자 또는 관리자가 할 수 있는 사항입니다.",
          "b_ids": "금연:제8조제1항, 금연:제5조제1항제1호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "흡연부스 설치 시 위치·환기 관련 규정",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "흡연부스를 설치할 경우 위치·환기 관련 규정을 따라야 합니다. 해당 장소의 규모, 특성 및 간접흡연 피해가능성 등을 고려하여 흡연구역의 면적, 위치 등을 정하여야 하고, 통풍이 잘 되도록 환기시설을 설치하여야 합니다. 다만 자연환기가 가능한 경우에는 환기시설을 설치하지 않을 수 있습니다.",
          "b_ids": "금연:제8조제2항제2호, 금연:제8조제2항제3호, 금연:제8조제2항제3호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
